SELECT "RUN_ID" AS "RUN_ID", "NODE" AS "NODE", "JOB_DURATION_d" AS "JOB_DURATION_d", "MAX_JOBS_COUNT_d" AS "MAX_JOBS_COUNT_d" 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' ORDER BY "JOB_DURATION_d" DESC, "RUN_ID" ASC 
 LIMIT 30;